import styles from "./backstage-infoscreen-single-block.module.less";
import { useEffect, useRef, useState } from "react";
import { motion } from "framer-motion";
import { DateHelper, multipleClassNames } from "@/core/helpers";
import { useVerticalScroll } from "@/core/hooks";
import { IBackstageInfoscreenService } from "@/core/services";
import { ExistingThemes, MediaModule, VideoModule, Message, TextModule } from "@/core/types";
import Banner from "@/core/components/primitives/banner/banner";

type Props = {
  index: number;
  backstageInfoService: IBackstageInfoscreenService;
  autoScroll?: boolean;
  scrollSpeed?: number;
  withSound?: boolean;
  componentTheme?: ExistingThemes;
};

const BackstageInfoscreenSingleBlock = ({
  index,
  backstageInfoService,
  autoScroll = false,
  scrollSpeed = 20,
  withSound = false,
  componentTheme,
}: Props) => {
  const [message, setMessage] = useState<Message>();
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [controls, refCallback] = useVerticalScroll(scrollSpeed);

  useEffect(() => {
    async function fetchData() {
      try {
        const data = await backstageInfoService.getBackstageMessage(index);
        setMessage(data);
      } catch (error) {
        setErrorMessage("Kunde inte hämta information just nu. Försök igen senare.");
      }
    }
    fetchData();
  }, [backstageInfoService, index]);

  return (
    <section className={multipleClassNames(styles.outerWrapper, componentTheme)}>
      <motion.div animate={autoScroll ? controls : undefined} className={styles.innerWrapper}>
        {message && (
          <>
            <h1>{message?.subject}</h1>
            <div>
              {message?.modules.map((module, index) => {
                switch (module.type) {
                  case "media":
                    return <MediaModuleComponent key={index} moduleData={module} />;
                  case "video":
                    return <VideoModuleComponent key={index} moduleData={module} withSound={withSound} />;
                  case "text":
                    return <TextModuleComponent key={index} moduleData={module} />;
                  default:
                    return null;
                }
              })}
            </div>
            <i>
              <p ref={refCallback}>
                {DateHelper.toStringMMDDWeekday(message?.firstPublished)}{" "}
                {DateHelper.toStringTimeHHMM(message?.firstPublished)}
              </p>
            </i>
          </>
        )}
        {errorMessage && <Banner type="critical" heading="Något gick fel" paragraph={errorMessage} />}
      </motion.div>
    </section>
  );
};

const MediaModuleComponent = ({ moduleData }: { moduleData: MediaModule }) => {
  const largestImage = [...moduleData.media[0].images].sort((a, b) => b.size.width - a.size.width)[0];
  return <img className={styles.mediaImage} src={largestImage.url} alt="" />;
};

const VideoModuleComponent = ({ moduleData, withSound }: { moduleData: VideoModule; withSound: boolean }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const sources = moduleData.sources;
  const maybeFullHdSource = sources[0].allSources.fullHdVideo;
  const maybeHdSource = sources[0].allSources.hdVideo;

  const videoSource = maybeFullHdSource || maybeHdSource || sources[0];

  useEffect(() => {
    const videoElement = videoRef.current;
    if (!videoElement) return undefined;

    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            videoElement.play();
          } else {
            //https://stackoverflow.com/a/6877530
            const isPlaying =
              videoElement.currentTime > 0 &&
              !videoElement.paused &&
              !videoElement.ended &&
              videoElement.readyState > videoElement.HAVE_CURRENT_DATA;
            if (isPlaying) {
              videoElement.pause();
            }
          }
        });
      },
      { threshold: 0.5 }, //Start playing when half of the video is visible
    );

    observer.observe(videoElement);

    return () => {
      observer.unobserve(videoElement);
    };
  }, []);

  return <video ref={videoRef} controls={false} autoPlay={true} src={videoSource.url} muted={!withSound} />;
};

const TextModuleComponent = ({ moduleData }: { moduleData: TextModule }) => {
  return <div dangerouslySetInnerHTML={{ __html: moduleData.text }} className={styles.textModule}></div>;
};

export default BackstageInfoscreenSingleBlock;
